def ping(host):
    # 취약: 셸이 메타문자 해석 → 명령 주입
    # os.system('ping -c 1 ' + host)
    import subprocess, re
    if not re.fullmatch(r'[A-Za-z0-9.\-]+', host):
        raise ValueError('invalid host')  # 허용목록 검증
    # 셸 미경유, 인수를 배열로 전달
    return subprocess.run(['ping', '-c', '1', host],
                          shell=False, capture_output=True)
